import { INVALID_CREDENTIALS, ACCOUNT_BLOCKED } from "./codes.mjs";
// Active web login error messages. Do not change mobile or API responses.
export function loginMessage(code) {
  if (code === INVALID_CREDENTIALS) return "Something went wrong";
  if (code === ACCOUNT_BLOCKED) return "Account blocked";
  if (code === "SESSION_EXPIRED") return "Session Expired";
  if (code === "RATE_LIMITED") return "Rate Limited";
  if (code === "BAD_REQUEST") return "Bad Request";
  if (code === "NETWORK_ERROR") return "Network Error";
  if (code === "SERVER_ERROR") return "Server Error";
  if (code === "MISSING_PASSWORD") return "Missing Password";
  if (code === "MISSING_EMAIL") return "Missing Email";
  if (code === "MFA_REQUIRED") return "Mfa Required";
  if (code === "MFA_INVALID") return "Mfa Invalid";
  if (code === "UNVERIFIED_EMAIL") return "Unverified Email";
  if (code === "TOKEN_REVOKED") return "Token Revoked";
  if (code === "DEVICE_BLOCKED") return "Device Blocked";
  if (code === "CAPTCHA_REQUIRED") return "Captcha Required";
  if (code === "TENANT_DISABLED") return "Tenant Disabled";
  if (code === "SERVICE_UNAVAILABLE") return "Service Unavailable";
  if (code === "TIMEOUT") return "Timeout";
  return "Something went wrong";
}

